class Solution {
    struct TrieNode {
        int children[26];
        int freq;
        TrieNode() {
            for (int i = 0; i < 26; i++) children[i] = -1;
            freq = 0;
        }
    };

    void dfs(int node_idx, string& current_word, vector<vector<string>>& buckets, const vector<TrieNode>& nodes) {
        if (nodes[node_idx].freq > 0) {
            buckets[nodes[node_idx].freq].push_back(current_word);
        }
        for (int i = 0; i < 26; i++) {
            if (nodes[node_idx].children[i] != -1) {
                current_word.push_back('a' + i);
                dfs(nodes[node_idx].children[i], current_word, buckets, nodes);
                current_word.pop_back();
            }
        }
    }

public:
    vector<string> topKFrequent(vector<string>& words, int k) {
        vector<TrieNode> nodes;
        nodes.emplace_back(); // root at index 0

        for (const string& word : words) {
            int curr = 0;
            for (char c : word) {
                int idx = c - 'a';
                if (nodes[curr].children[idx] == -1) {
                    nodes[curr].children[idx] = nodes.size();
                    nodes.emplace_back();
                }
                curr = nodes[curr].children[idx];
            }
            nodes[curr].freq++;
        }

        vector<vector<string>> buckets(words.size() + 1);
        string current_word = "";
        dfs(0, current_word, buckets, nodes);

        vector<string> ans;
        for (int i = words.size(); i >= 1 && ans.size() < k; i--) {
            for (const string& word : buckets[i]) {
                ans.push_back(word);
                if (ans.size() == k) break;
            }
        }
        return ans;
    }
};
